#include <print>
#include <vector>

int main() {
    std::vector<std::vector<int>> a = {{1, 2, 3}, {4, 5, 6}};
    std::vector<std::vector<int>> p(3, std::vector<int>(4, 0));
    for (int i = 1; i <= 2; ++i)
        for (int j = 1; j <= 3; ++j)
            p[i][j] = p[i-1][j] + p[i][j-1] - p[i-1][j-1] + a[i-1][j-1];
    std::println("整块 = {}", p[2][3]);
    std::println("行 0 列 0~2 的和 = {}", p[1][3] - p[0][3] - p[1][0] + p[0][0]);
    return 0;
}
