#include <print>
#include <vector>

int main() {
    std::vector<std::vector<int>> a = {{1, 2, 3}, {4, 5, 6}};
    std::vector<std::vector<int>> p(2, std::vector<int>(3, 0));
    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 3; ++j)
            p[i][j] = a[i][j] + a[i][j];
    std::println("行 0 列 0~2 的和 = {}", p[1][2]);
    return 0;
}

